local UIActionCityStoreItemNode = Class("UIActionCityStoreItemNode")
function UIActionCityStoreItemNode:__init()
    self._data = nil
    self._cb = nil
end

function UIActionCityStoreItemNode:__delete()
    self._data = nil
    self._cb = nil
end

function UIActionCityStoreItemNode:Awake()
end

function UIActionCityStoreItemNode:Start()
    SetButtonAction(self.BtnNode, Bind(self, self.OnBtnBuy))
end

function UIActionCityStoreItemNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb

    self:FillSelf()
end

function UIActionCityStoreItemNode:FillSelf()
    local vo = ActionUtils.GetRegionStoreGoodsVo(self._data.id)
    if not vo then
        return
    end
    local type = GoodsUtils.GetIdType(vo.sourceID)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.sourceID)
    CfUtils.SetActive(self.GroupDesc2, checkNumber(self._data.stock) > 0 and checkNumber(self._data.stock) ~= -1)

    if goodsVo then
        CfUtils.FillImage(self.GoodQuality, GoodsUtils.GetFishBgByQualityType(goodsVo.quality))
        CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(vo.sourceID))

        CfUtils.SetActive(self.Equip, type == Constants.IDType.Equipment)
        --CfUtils.SetActive(self.GroupDesc2, type ~= Constants.IDType.Equipment)
        CfUtils.FillText(self.TxtDesc1, goodsVo.name)
    end 
    CfUtils.FillText(self.TxtNumber, self._data.stock)        --剩余数量
    CfUtils.FillText(self.Txtprice, vo.price)
    CfUtils.FillImage(self.Icon, GoodsConfMgr:GetInstance():GetPhotoPathById(vo.currency))
    CfUtils.SetActive(self.FinishGroup, checkNumber(self._data.stock) <= 0 and checkNumber(self._data.stock) ~= -1)

    if type == Constants.IDType.Equipment then
        CfUtils.FillImage(self.Type.transform:Find("ImgIcon"), EquipUtils.GetEquipmentSetIcon(vo.sourceID))
        --卖的没等级
        --CfUtils.SetUISwitchImage(self.ImgStrengthen, 1)
        CfUtils.SetActive(self.ImgStrengthen, false)
        CfUtils.SetActive(self.ImgStar, false)
    end

    local isUnlock = ActionUtils.IsUnlockItem(self._data.id)
    CfUtils.SetActive(self.LockGroup, not isUnlock)
    if not isUnlock then
        CfUtils.FillText(self.TxtLock, localize("区域调查等级_num_\n级解锁", {_num_ = vo.unlock}))
    end
end

function UIActionCityStoreItemNode:OnBtnBuy()
    local vo = ActionUtils.GetRegionStoreGoodsVo(self._data.id)

    local isUnlock = ActionUtils.IsUnlockItem(self._data.id)
    if not isUnlock then
        GameUtils.Toast(localize("区域调查等级_num_\n级解锁", {_num_ = vo.unlock}))
        return
    elseif self._data.stock ~= -1 and self._data.stock <= 0 then
        GameUtils.Toast(localize("已售完"))
        return
    end

    local t = {
        goodsId = vo.sourceID,
        consumeGoodsId = vo.currency,
        consumeNum = vo.price,
        maxBuyNum = (self._data.stock == -1 and 99 or self._data.stock),
        remainTime = ActionComponent:GetStoreRemainTime(),
        buyCb = function(buyNum)
            GameUtils.Request(Interfaces.RegionalMerchantGetBuy, {shopId = self._data.id, num = buyNum}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                local jsonData = response.data
                
                if self._data.stock ~= -1 then
                    self._data.stock = self._data.stock - buyNum
                end
                GoodsUtils.DrawRewards(jsonData.rewards)
                GoodsUtils.DrawRewards({{
                    goodsId = vo.currency,
                    num = -(buyNum * checkNumber(vo.price))
                }}, true)

                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = jsonData.rewards}})

                self:FillSelf()
                if self._cb then
                    self._cb(buyNum)
                end
            end)
        end,
    }

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = t}, {
    })
end

function UIActionCityStoreItemNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionCityStoreItemNode